277	// consumeV2FetchPack walks a protocol v2 fetch response envelope
278	// (acknowledgments / shallow-info / packfile sections) and hands the
279	// demuxed packfile stream to consumer. A response that ends without ever
280	// delivering a packfile is reported as io.ErrUnexpectedEOF rather than as
281	// silent success: by the time we reach here wants is non-empty (callers
282	// short-circuit the up-to-date case earlier), so the server owes us a
283	// packfile section. This mirrors the sibling openV2PackStream — previously a
284	// truncated or pack-less response let a fetch "succeed" having stored nothing.
285	func consumeV2FetchPack(
286		r io.Reader,
287		verbose bool,
288		progressOut io.Writer,
289		consumer func(io.Reader) error,
290	) error {
291		reader := NewPacketReader(r)
292		expectPackfile := false
293		for {
294			kind, payload, err := reader.ReadPacket()
295			if err != nil {
296				if errors.Is(err, io.EOF) {
297					if expectPackfile {
298						return errors.New("expected packfile to be sent after 'ready'")
299					}
300					return io.ErrUnexpectedEOF
301				}
302				return fmt.Errorf("decode protocol v2 fetch response: %w", err)
303			}
304			switch kind {
305			case PacketFlush:
306				if expectPackfile {
307					return errors.New("expected packfile to be sent after 'ready'")
308				}
309				return io.ErrUnexpectedEOF
310			case PacketDelim, PacketResponseEnd:
311				continue
312			case PacketData:
313				line := string(payload)
314				if strings.HasPrefix(line, "ERR ") {
315					return errors.New("remote: " + line[4:])
316				}
317				switch line {
318				case "packfile\n":
319					demux := sideband.NewDemuxer(sideband.Sideband64k, reader.BufReader())
320					demux.Progress = progressSink(verbose, "source: ", progressOut)
321					return consumer(demux)
322				case "acknowledgments\n":
323					ready, err := skipV2Acknowledgments(reader)
324					if err != nil {
325						return err
326					}
327					expectPackfile = ready
328				case "shallow-info\n":
329					expectPackfile = true
330					if err := SkipSection(reader); err != nil {
331						return err
332					}
333				default:
334					return fmt.Errorf("unexpected protocol v2 fetch section %q", strings.TrimSpace(line))
335				}
336			}
337		}
338	}
339	
340	func openV2PackStream(body io.ReadCloser, verbose bool, progressOut io.Writer) (io.ReadCloser, error) {
341		reader := NewPacketReader(body)
342		for {
343			kind, payload, err := reader.ReadPacket()
344			if err != nil {
345				if errors.Is(err, io.EOF) {
346					return nil, io.ErrUnexpectedEOF
347				}
348				return nil, fmt.Errorf("decode protocol v2 fetch response: %w", err)
349			}
350			switch kind {
351			case PacketFlush:
352				return nil, io.ErrUnexpectedEOF
353			case PacketDelim, PacketResponseEnd:
354				continue
355			case PacketData:
356				line := string(payload)
357				if strings.HasPrefix(line, "ERR ") {
358					return nil, errors.New("remote: " + line[4:])
359				}
360				switch line {
361				case "packfile\n":
362					demux := sideband.NewDemuxer(sideband.Sideband64k, reader.BufReader())
363					demux.Progress = progressSink(verbose, "source: ", progressOut)
364					return &wrappedRC{
365						Reader: demux,
366						Closer: body,
367					}, nil
368				case "acknowledgments\n":
369					if _, err := skipV2Acknowledgments(reader); err != nil {
370						return nil, err
371					}
372				case "shallow-info\n":
373					if err := SkipSection(reader); err != nil {
374						return nil, err
375					}
376				default:
377					return nil, fmt.Errorf("unexpected protocol v2 fetch section %q", strings.TrimSpace(line))
378				}
379			}
380		}
381	}
382	
383	func skipV2Acknowledgments(reader *PacketReader) (bool, error) {
384		ready := false
385		for {
386			kind, payload, err := reader.ReadPacket()
387			if err != nil {
388				return false, err
389			}
390			switch kind {
391			case PacketFlush:
392				if ready {
393					return false, errors.New("expected packfile to be sent after 'ready'")
394				}
395				return false, errors.New("protocol v2 fetch response ended without packfile after acknowledgments")
396			case PacketDelim:
397				if !ready {
398					return false, errors.New("unexpected delimiter in acknowledgments section without 'ready'")
399				}
400				return true, nil
401			case PacketData:
402				line := string(payload)
403				switch {
404				case line == "NAK\n", strings.HasPrefix(line, "ACK "):
405					continue
406				case line == "ready\n":
407					ready = true
408				default:
409					return false, fmt.Errorf("unexpected acknowledgment line %q", strings.TrimSpace(line))
410				}
411			case PacketResponseEnd:
412				return false, fmt.Errorf("unexpected packet type %v in acknowledgments section", kind)
413			default:
414				return false, fmt.Errorf("unexpected packet type %v in acknowledgments section", kind)
415			}
416		}
417	}
