421	// buildV1UploadPackBody encodes a v1 upload-pack request body for stateless-rpc HTTP.
422	func buildV1UploadPackBody(
423		adv *packp.AdvRefs,
424		desired map[plumbing.ReferenceName]DesiredRef,
425		targetRefs map[plumbing.ReferenceName]plumbing.Hash,
426		includeTags bool,
427		verbose bool,
428	) ([]byte, *capability.List, error) {
429		wants := collectWants(desired)
430		haves := SortedUniqueHashes(refValues(targetRefs))
431		if len(wants) == 0 {
432			return nil, nil, git.NoErrAlreadyUpToDate
433		}
434	
435		req := &packp.UploadRequest{}
436		req.Wants = wants
437		if !verbose && adv.Capabilities.Supports(capability.NoProgress) {
438			req.Capabilities.Set(capability.NoProgress)
439		}
440		if includeTags && adv.Capabilities.Supports(capability.IncludeTag) {
441			req.Capabilities.Set(capability.IncludeTag)
442		}
443		// Prefer sideband64k over sideband (issue #4).
444		if sb := PreferredSideband(&adv.Capabilities); sb != "" {
445			req.Capabilities.Set(sb)
446		}
447		if adv.Capabilities.Supports(capability.OFSDelta) {
448			req.Capabilities.Set(capability.OFSDelta)
449		}
450		// NOTE: we intentionally do not request capability.ThinPack. The relayed
451		// pack must stay self-contained because callers (e.g. replicate) forward
452		// it to receive-pack servers that may advertise "no-thin".
453		// planner.SupportsReplicateRelay depends on this invariant — if you add
454		// thin-pack support here, update that check to gate on target NoThin.
455	
456		var buf bytes.Buffer
457		if err := req.Encode(&buf); err != nil {
458			return nil, nil, fmt.Errorf("encode upload-request: %w", err)
459		}
460		uphav := &packp.UploadHaves{Haves: haves, Done: true}
461		if err := uphav.Encode(&buf); err != nil {
462			return nil, nil, fmt.Errorf("encode upload-haves: %w", err)
463		}
464		return buf.Bytes(), &req.Capabilities, nil
465	}
