467	func fetchToStoreV1(
468		ctx context.Context,
469		store storer.Storer,
470		conn Conn,
471		adv *packp.AdvRefs,
472		desired map[plumbing.ReferenceName]DesiredRef,
473		targetRefs map[plumbing.ReferenceName]plumbing.Hash,
474		verbose bool,
475	) error {
476		body, caps, err := buildV1UploadPackBody(adv, desired, targetRefs, hasTag(desired), verbose)
477		if err != nil {
478			return err
479		}
