502	func fetchPackV1(
503		ctx context.Context,
504		conn Conn,
505		adv *packp.AdvRefs,
506		desired map[plumbing.ReferenceName]DesiredRef,
507		targetRefs map[plumbing.ReferenceName]plumbing.Hash,
508		verbose bool,
509	) (io.ReadCloser, error) {
510		body, caps, err := buildV1UploadPackBody(adv, desired, targetRefs, hasTag(desired), verbose)
511		if err != nil {
512			return nil, err
513		}
514		reader, err := PostRPCStream(ctx, conn, transport.UploadPackService, body, false, "upload-pack fetch")
515		if err != nil {
516			return nil, fmt.Errorf("source upload-pack: %w", err)
517		}
518	
519		buffered := bufio.NewReader(reader)
520		var srvResp packp.ServerResponse
521		if decErr := srvResp.Decode(buffered); decErr != nil {
522			_ = reader.Close()
523			return nil, fmt.Errorf("decode server response: %w", decErr)
524		}
525		if drainErr := drainTrailingNAKs(buffered); drainErr != nil {
526			_ = reader.Close()
527			return nil, fmt.Errorf("drain server response: %w", drainErr)
528		}
529		return &wrappedRC{
530			Reader: buildSidebandReader(caps, buffered, progressSink(verbose, "source: ", conn.ProgressWriter())),
531			Closer: reader,
532		}, nil
533	}
534	
535	// drainTrailingNAKs consumes any extra "NAK\n" pktlines left in the stream
536	// after ServerResponse.Decode. go-git's upload-pack server emits a second NAK
537	// when haves were sent but none were reachable from the wants (see
538	// plumbing/transport/upload_pack.go), while go-git's ServerResponse.Decode
539	// stops after the first NAK. The remainder would otherwise be misread by the
540	// sideband demuxer as a frame with channel byte 'N' ("unknown channel NAK").
541	//
542	// A stream that runs out before we can peek 8 bytes carries no trailing NAK
543	// to drain, so we silently stop. The downstream consumer observes the same
544	// underlying read error on its first read.
545	func drainTrailingNAKs(r *bufio.Reader) error {
546		for {
547			header, err := r.Peek(8)
548			if len(header) < 8 || !bytes.Equal(header, []byte("0008NAK\n")) {
549				_ = err
550				return nil
551			}
552			if _, err := r.Discard(8); err != nil {
553				return fmt.Errorf("discard trailing NAK: %w", err)
554			}
555		}
556	}
