558	// buildSidebandReader wraps a reader with sideband demuxing if the negotiated
559	// capabilities include sideband support. Delegates to PreferredSideband (issue #4).
560	func buildSidebandReader(caps *capability.List, reader io.Reader, progress sideband.Progress) io.Reader {
561		sb := PreferredSideband(caps)
562		if sb == "" {
563			return reader
564		}
565		var t sideband.Type
566		if sb == capability.Sideband64k {
567			t = sideband.Sideband64k
568		} else {
569			t = sideband.Sideband
570		}
571		d := sideband.NewDemuxer(t, reader)
572		d.Progress = progress
573		return d
574	}
