605	// SortedUniqueHashes deduplicates and sorts a hash slice.
606	func SortedUniqueHashes(input []plumbing.Hash) []plumbing.Hash {
607		seen := make(map[plumbing.Hash]struct{}, len(input))
608		out := make([]plumbing.Hash, 0, len(input))
609		for _, h := range input {
610			if _, ok := seen[h]; ok {
611				continue
612			}
613			seen[h] = struct{}{}
614			out = append(out, h)
615		}
616		plumbing.HashesSort(out)
617		return out
618	}
