// passthrough is a packp.Decoder that captures the raw response stream.
type passthrough struct {
	buf  bytes.Buffer
	held io.Reader // stashed for the "hold past Decode" experiment
	hold bool
}

func (p *passthrough) Decode(r io.Reader) error {
	if p.hold {
		p.held = r
		return nil
	}
	_, err := io.Copy(&p.buf, r)
	return err
}

func run(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %s: %v\n%s", strings.Join(args, " "), err, out)
	}
	return string(out)
}

func newServer(t *testing.T) (base string, bare string) {
	t.Helper()
	gitPath, err := exec.LookPath("git")
	if err != nil {
		t.Skipf("git not found: %v", err)
	}
	root := t.TempDir()
	bare = filepath.Join(root, "src.git")
	work := filepath.Join(root, "work")
	run(t, root, "init", "--bare", bare)
	run(t, root, "init", "-b", "main", work)
	run(t, work, "config", "user.name", "spike")
	run(t, work, "config", "user.email", "spike@example.com")
	if err := os.WriteFile(filepath.Join(work, "a.txt"), bytes.Repeat([]byte("hello\n"), 500), 0o644); err != nil {
		t.Fatal(err)
	}
	run(t, work, "add", "a.txt")
	run(t, work, "commit", "-m", "one")
	run(t, work, "remote", "add", "origin", bare)
	run(t, work, "push", "origin", "HEAD:refs/heads/main")

