		Path: gitPath,
		Args: []string{"http-backend"},
		Env:  []string{"GIT_PROJECT_ROOT=" + root, "GIT_HTTP_EXPORT_ALL=1"},
	}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		h.ServeHTTP(w, r)
	}))
	t.Cleanup(srv.Close)
	return srv.URL + "/src.git", bare
}

func handshake(t *testing.T, base string) (transport.Session, plumbing.Hash) {
	t.Helper()
	u, err := url.Parse(base)
	if err != nil {
		t.Fatal(err)
	}
	tr := githttp.NewTransport(githttp.Options{})
	sess, err := tr.Handshake(context.Background(), &transport.Request{
		URL:      u,
		Command:  transport.UploadPackService,
		Protocol: protocol.V2,
	})
	if err != nil {
		t.Fatalf("handshake: %v", err)
	}
	t.Cleanup(func() { _ = sess.Close() })

	refs, err := sess.GetRemoteRefs(context.Background(), nil)
	if err != nil {
		t.Fatalf("GetRemoteRefs: %v", err)
	}
	for _, r := range refs.References {
		if r.Name() == plumbing.NewBranchReferenceName("main") {
			return sess, r.Hash()
		}
	}
	t.Fatalf("refs/heads/main not advertised; got %v", refs.References)
	return nil, plumbing.ZeroHash
}

// SPIKE 1: does a pass-through decoder yield the raw pack stream?
func TestPassthroughDecoderYieldsRawStream(t *testing.T) {
	base, _ := newServer(t)
	sess, head := handshake(t, base)

	cmdr, ok := sess.(transport.Commander)
	if !ok {
		t.Fatal("smart HTTP session does not implement transport.Commander")
	}
	t.Log("session implements transport.Commander: OK")

	p := &passthrough{}
	args := &packp.FetchArgs{Wants: []plumbing.Hash{head}, Done: true, NoProgress: true, OFSDelta: true}
	if err := cmdr.Command(context.Background(), "fetch", args, p); err != nil {
		t.Fatalf("Command(fetch): %v", err)
	}
	raw := p.buf.Bytes()
	t.Logf("captured %d raw bytes", len(raw))
	if !bytes.Contains(raw, []byte("packfile\n")) {
		t.Errorf("no packfile section header in raw stream; first 200 bytes: %q", raw[:min(200, len(raw))])
	}
	if !bytes.Contains(raw, []byte("PACK")) {
		t.Error("no PACK signature in raw stream")
	}
	// Show the shape of the envelope so we can see what pass-through must skip.
	t.Logf("first 120 bytes: %q", raw[:min(120, len(raw))])
	t.Logf("last 16 bytes:   %q", raw[max(0, len(raw)-16):])
}

// SPIKE 2: can the reader be held open past Decode's return and relayed later?
func TestReaderHeldPastDecodeIsDead(t *testing.T) {
	base, _ := newServer(t)
	sess, head := handshake(t, base)
	cmdr := sess.(transport.Commander)

	p := &passthrough{hold: true}
	args := &packp.FetchArgs{Wants: []plumbing.Hash{head}, Done: true, NoProgress: true, OFSDelta: true}
	if err := cmdr.Command(context.Background(), "fetch", args, p); err != nil {
		t.Fatalf("Command(fetch): %v", err)
	}
	if p.held == nil {
		t.Fatal("decoder did not capture reader")
	}
	n, err := io.Copy(io.Discard, p.held)
	t.Logf("after Command returned, reading held reader gave n=%d err=%v", n, err)
	if n > 0 && err == nil {
		t.Log("UNEXPECTED: held reader still produced the full stream")
	} else {
		t.Log("CONFIRMED: held reader is dead once Command returns (body drained+closed)")
	}
}

func min(a, b int) int { if a < b { return a }; return b }
func max(a, b int) int { if a > b { return a }; return b }
