// relayDecoder streams the raw v2 fetch response straight into a sink,
// entirely inside Decode. This is the only shape HTTP's Command permits.
type relayDecoder struct {
	sink func(io.Reader) error
}

func (d *relayDecoder) Decode(r io.Reader) error { return d.sink(r) }

// SPIKE 3: relay the pack through Decode into a real external consumer
// (git index-pack --stdin), proving the stream survives a slow sink and
// that the pack is complete and self-contained.
func TestRelayInsideDecodeToRealConsumer(t *testing.T) {
	base, srcBare := newServer(t)
	sess, head := handshake(t, base)
	cmdr := sess.(transport.Commander)

	dst := filepath.Join(t.TempDir(), "dst.git")
	run(t, filepath.Dir(dst), "init", "--bare", dst)

	idx := exec.Command("git", "index-pack", "--stdin", "--fix-thin")
	idx.Dir = dst
	idx.Env = append(os.Environ(), "GIT_DIR="+dst)
	stdin, err := idx.StdinPipe()
	if err != nil {
		t.Fatal(err)
	}
	var idxOut bytes.Buffer
	idx.Stdout, idx.Stderr = &idxOut, &idxOut
	if err := idx.Start(); err != nil {
		t.Fatal(err)
	}

	var copied int64
	d := &relayDecoder{sink: func(r io.Reader) error {
		// Strip the v2 envelope the way git-sync's openV2PackStream does:
		// read pkt-lines until "packfile\n", then demux sideband into the sink.
		pack, derr := envelopeToPack(r)
		if derr != nil {
			return derr
		}
		copied, derr = io.Copy(stdin, pack)
		return derr
	}}

	args := &packp.FetchArgs{Wants: []plumbing.Hash{head}, Done: true, NoProgress: true, OFSDelta: true}
	cmdErr := cmdr.Command(context.Background(), "fetch", args, d)
	_ = stdin.Close()
	waitErr := idx.Wait()

	if cmdErr != nil {
		t.Fatalf("Command(fetch): %v", cmdErr)
	}
	if waitErr != nil {
		t.Fatalf("index-pack: %v\n%s", waitErr, idxOut.String())
	}
	t.Logf("relayed %d pack bytes through Decode; index-pack said: %s", copied, strings.TrimSpace(idxOut.String()))

	// The relayed pack must actually contain the source head.
	got := strings.TrimSpace(run(t, dst, "cat-file", "-t", head.String()))
	if got != "commit" {
		t.Fatalf("relayed pack does not contain source head %s (got type %q)", head, got)
	}
	t.Logf("CONFIRMED: relay inside Decode works end-to-end (src=%s)", srcBare)
}

// envelopeToPack advances r past the v2 fetch response envelope and returns a
// reader over the sideband-demuxed packfile, mirroring git-sync's
// openV2PackStream.
func envelopeToPack(r io.Reader) (io.Reader, error) {
	br := bufio.NewReader(r)
	for {
		l, line, err := pktline.ReadLine(br)
		if err != nil {
			return nil, err
		}
		if l == pktline.Flush || l == pktline.Delim || l == pktline.ResponseEnd {
			continue
		}
		switch strings.TrimSpace(string(line)) {
		case "packfile":
			return sideband.NewDemuxer(sideband.Sideband64k, br), nil
		case "acknowledgments", "shallow-info", "wanted-refs":
			continue
		default:
			if strings.HasPrefix(string(line), "NAK") || strings.HasPrefix(string(line), "ACK") ||
				strings.HasPrefix(string(line), "ready") {
				continue
			}
			return nil, io.ErrUnexpectedEOF
		}
	}
}
