137			// Closing stdin terminates the request: it bounds the v2
138			// flush-terminated read and, crucially, signals end-of-pack to the
139			// receive-pack handler, which copies the pack until EOF.
140			closeErr := proc.stdin.Close()
141			if err != nil {
142				copyErr <- err
143				return
144			}
145			copyErr <- closeErr
146		}()
147	
148		var resp io.Reader = proc.out
149		if v2 {
150			resp = newResponseEndReader(proc.out)
151		}
152		return &helperRPCStream{ctx: ctx, resp: resp, proc: proc, copyErr: copyErr}, nil
153	}
154	
155	// dial starts the helper process and opens a stateless-connect session for the
156	// service, consuming the helper's single-line acknowledgement. On success the
157	// helper is positioned to emit its advertisement.
158	func (c *HelperConn) dial(ctx context.Context, service string) (*helperProcess, error) {
159		// git invokes a remote helper as `git-remote-<scheme> <remote> <url>`.
160		// Passing the user-typed URL for both arguments matches git's handling of
161		// an anonymous (URL-only) remote, which is what git-sync always has.
162		cmd := exec.CommandContext(ctx, c.HelperPath, c.RawURL, c.RawURL)
163		// GIT_PROTOCOL=version=2 makes the helper advertise stateless-connect; we
164		// drive stateless-connect directly regardless, but this keeps the helper's
165		// own negotiation aligned with how we use it.
166		cmd.Env = append(os.Environ(), "GIT_PROTOCOL="+GitProtocolV2)
167		stderr := &sshCommandError{}
168		cmd.Stderr = stderr
169		stdout, err := cmd.StdoutPipe()
170		if err != nil {
171			return nil, fmt.Errorf("open helper stdout: %w", err)
172		}
173		stdin, err := cmd.StdinPipe()
174		if err != nil {
175			return nil, fmt.Errorf("open helper stdin: %w", err)
176		}
177		if err := cmd.Start(); err != nil {
178			return nil, fmt.Errorf("start remote helper %s: %w", c.HelperPath, stderr.wrap(err))
179		}
180		proc := &helperProcess{
181			cmd:    cmd,
182			stdin:  stdin,
183			stdout: stdout,
184			out:    bufio.NewReaderSize(stdout, 65536),
185			stderr: stderr,
186		}
187		// Probe capabilities first so an incompatible helper produces a clear error
188		// instead of a cryptic mid-protocol failure. This is a local exchange — no
189		// network round trip happens until stateless-connect below.
190		caps, err := proc.readCapabilities()
191		if err != nil {
192			return nil, fmt.Errorf("probe remote helper %s: %w", c.HelperPath, errors.Join(err, proc.cleanup()))
193		}
194		if !slices.Contains(caps, "stateless-connect") {
195			unsupported := fmt.Errorf("remote helper %s does not support stateless-connect (advertises: %s); git-sync needs a stateless-connect-capable helper such as git-remote-entire",
196				c.HelperPath, strings.Join(caps, " "))
197			return nil, errors.Join(unsupported, proc.cleanup())
198		}
199		if _, err := io.WriteString(stdin, "stateless-connect "+service+"\n"); err != nil {
200			return nil, fmt.Errorf("request stateless-connect %s: %w", service, errors.Join(err, proc.cleanup()))
201		}
202		if err := proc.readAck(); err != nil {
203			return nil, fmt.Errorf("stateless-connect %s: %w", service, errors.Join(err, proc.cleanup()))
204		}
205		return proc, nil
206	}
207	
208	// helperProcess wraps a single helper invocation and its pipes.
209	type helperProcess struct {
210		cmd    *exec.Cmd
211		stdin  io.WriteCloser
212		stdout io.ReadCloser
213		out    *bufio.Reader
214		stderr *sshCommandError
215	
216		stdinOnce sync.Once
217	}
218	
219	// readCapabilities issues the helper's `capabilities` command and returns the
220	// advertised capability names (the token before any argument on each line),
221	// reading until the blank terminator line.
222	func (p *helperProcess) readCapabilities() ([]string, error) {
223		if _, err := io.WriteString(p.stdin, "capabilities\n"); err != nil {
224			return nil, fmt.Errorf("request capabilities: %w", err)
225		}
226		var caps []string
227		for {
228			line, err := p.out.ReadString('\n')
229			if err != nil {
230				return nil, fmt.Errorf("read capabilities: %w", p.stderr.wrap(err))
231			}
232			if line = strings.TrimRight(line, "\r\n"); line == "" {
233				return caps, nil
234			}
235			name, _, _ := strings.Cut(line, " ")
236			caps = append(caps, name)
237		}
238	}
239	
240	// readAck consumes the helper's stateless-connect response line: an empty line
241	// means the connection is established, "fallback" means it can't proxy this
242	// service, and anything else is an error (with captured stderr).
243	func (p *helperProcess) readAck() error {
244		line, err := p.out.ReadString('\n')
245		if err != nil {
246			return fmt.Errorf("read helper response: %w", p.stderr.wrap(err))
247		}
248		switch strings.TrimRight(line, "\r\n") {
249		case "":
250			return nil
251		case "fallback":
252			return errors.New("remote helper cannot proxy this service (fallback)")
253		default:
254			return fmt.Errorf("unexpected helper response %q: %s", strings.TrimRight(line, "\r\n"), p.stderr.String())
255		}
256	}
257	
258	func (p *helperProcess) closeStdin() error {
259		var err error
260		p.stdinOnce.Do(func() { err = p.stdin.Close() })
261		if err != nil {
262			return fmt.Errorf("close helper stdin: %w", err)
263		}
264		return nil
265	}
266	
267	func (p *helperProcess) wait() error {
268		if err := p.cmd.Wait(); err != nil {
269			return p.stderr.wrap(fmt.Errorf("remote helper: %w", err))
270		}
271		return nil
272	}
273	
274	// maxDrainBytes bounds finish's trailing-output drain. A compliant helper
275	// writes nothing of consequence after the advertisement, so this only ever
276	// absorbs a small tail. The bound matters because an unbounded drain against a
277	// helper that keeps writing never returns — which would defeat
278	// readAdvertisement's own limit by hanging here instead of reporting it.
279	const maxDrainBytes = 1 << 20
280	
281	// finish closes the request side and waits for the helper to exit cleanly,
282	// draining any trailing output so cmd.Wait doesn't race the stdout pipe. Used
283	// by RequestInfoRefs, which needs only the advertisement.
284	func (p *helperProcess) finish() error {
285		closeErr := p.closeStdin()
286		//nolint:errcheck // best-effort drain before Wait; exit status is authoritative
287		drained, _ := io.Copy(io.Discard, io.LimitReader(p.out, maxDrainBytes+1))
288		if drained > maxDrainBytes {
289			// Still producing well past any legitimate tail. Close the pipe so the
290			// write side fails and the process can exit, instead of blocking
291			// forever on a full pipe and taking p.wait() with it.
292			_ = p.stdout.Close()
293		}
294		return errors.Join(closeErr, p.wait())
295	}
296	
297	// cleanup force-tears-down the process on an error path.
298	func (p *helperProcess) cleanup() error {
299		_ = p.closeStdin() //nolint:errcheck // force-teardown path; wait status is the reported error
300		_ = p.stdout.Close()
301		return p.wait()
302	}
303	
304	// readAdvertisement reads raw pkt-lines up to and including the first flush
305	// (0000) and returns them verbatim. This is the helper's service advertisement;
306	// the trailing flush is preserved because both advertisement decoders consume
307	// it as the section terminator.
308	//
309	// Accumulation is bounded by MaxAdvertisementBytes, the same ceiling the HTTP
310	// and SSH transports use: a helper that streams pkt-lines and never sends the
311	// flush would otherwise grow this buffer until the process died.
312	func readAdvertisement(br *bufio.Reader) ([]byte, error) {
313		var buf bytes.Buffer
314		var scratch []byte
315		for {
316			kind, frame, err := readRawPktLine(br, scratch)
317			if err != nil {
318				return nil, fmt.Errorf("read advertisement pkt-line: %w", err)
319			}
320			buf.Write(frame)
321			if buf.Len() > MaxAdvertisementBytes {
322				return nil, fmt.Errorf("helper advertisement exceeds %d byte limit", MaxAdvertisementBytes)
323			}
324			scratch = frame // reuse the (possibly grown) backing buffer next iteration
325			if kind == PacketFlush {
326				return buf.Bytes(), nil
327			}
328		}
329	}
330	
331	// responseEndReader re-emits a helper's framed v2 response verbatim, returning
332	// io.EOF when it reaches the stateless-connect response-end (0002) packet. The
333	// 0002 is consumed but never forwarded, so the downstream protocol parser sees
334	// exactly the same bytes it would from an HTTP response body (which ends at the
335	// connection's EOF instead). The frame buffer is reused across packets, so
336	// relaying a multi-GB pack costs no per-packet allocation.
337	type responseEndReader struct {
338		src     *bufio.Reader
339		buf     []byte // reused backing for the current frame
340		pending []byte // unread bytes of the current frame (sub-slice of buf)
341		done    bool
342	}
343	
344	func newResponseEndReader(src *bufio.Reader) *responseEndReader {
345		return &responseEndReader{src: src}
346	}
347	
348	func (r *responseEndReader) Read(p []byte) (int, error) {
349		for len(r.pending) == 0 {
350			if r.done {
351				return 0, io.EOF
352			}
353			if err := r.fill(); err != nil {
354				return 0, err
355			}
356		}
357		n := copy(p, r.pending)
358		r.pending = r.pending[n:]
359		return n, nil
360	}
361	
362	func (r *responseEndReader) fill() error {
363		kind, frame, err := readRawPktLine(r.src, r.buf)
364		if err != nil {
365			return fmt.Errorf("read response pkt-line: %w", err)
366		}
367		if kind == PacketResponseEnd {
368			r.done = true
369			return io.EOF
370		}
371		r.buf = frame // retain the grown backing for the next fill
372		r.pending = frame
373		return nil
374	}
375	
376	// helperRPCStream is the io.ReadCloser returned for a helper RPC response. It
377	// forwards reads from the (optionally response-end-bounded) helper stdout and,
378	// on Close, tears the process down: closing both pipes (which unblocks the body
379	// writer if the consumer bailed mid-stream), then joining the body-copy error,
380	// the process exit status, and any captured stderr.
381	type helperRPCStream struct {
382		ctx     context.Context
383		resp    io.Reader
384		proc    *helperProcess
385		copyErr <-chan error
386	
387		closeOnce sync.Once
388		closeErr  error
389	}
390	
391	func (s *helperRPCStream) Read(p []byte) (int, error) {
392		n, err := s.resp.Read(p)
393		return n, err //nolint:wrapcheck // io.Reader contract requires forwarding EOF and stream errors as-is
394	}
395	
396	func (s *helperRPCStream) Close() error {
397		s.closeOnce.Do(func() {
398			_ = s.proc.closeStdin() //nolint:errcheck // unblocks the body writer; copy/wait errors below are authoritative
399			closeOut := s.proc.stdout.Close()
400			copyErr := <-s.copyErr
401			waitErr := s.proc.wait()
402	
403			s.closeErr = errors.Join(copyErr, waitErr)
404			if s.closeErr == nil && closeOut != nil && !errors.Is(closeOut, os.ErrClosed) {
405				s.closeErr = closeOut
406			}
407			if s.ctx != nil && s.ctx.Err() != nil {
408				s.closeErr = errors.Join(s.ctx.Err(), s.closeErr)
409			}
410		})
411		return s.closeErr
412	}

