 13	// V2Capabilities represents a parsed protocol v2 capability advertisement.
 14	type V2Capabilities struct {
 15		Caps map[string]string
 16	}
 17	
 18	// Supports reports whether the server advertises the named capability.
 19	func (c *V2Capabilities) Supports(name string) bool {
 20		if c == nil {
 21			return false
 22		}
 23		_, ok := c.Caps[name]
 24		return ok
 25	}
 26	
 27	// Value returns the value string for the named capability.
 28	func (c *V2Capabilities) Value(name string) string {
 29		if c == nil {
 30			return ""
 31		}
 32		return c.Caps[name]
 33	}
 34	
 35	// FetchSupports checks whether a specific feature is listed in the
 36	// "fetch" capability value (space-separated feature list).
 37	func (c *V2Capabilities) FetchSupports(feature string) bool {
 38		return c.commandSupports("fetch", feature)
 39	}
 40	
 41	// LSRefsSupports checks whether a specific feature is listed in the "ls-refs"
 42	// capability value (space-separated feature list). The only feature defined
 43	// today is "unborn": a server advertising it will report an unborn HEAD as an
 44	// explicit "unborn HEAD symref-target:<ref>" line, which is the difference
 45	// between a repository asserting it has no commits and a response that merely
 46	// carries no ref lines. Protocol v2 forbids sending a command argument the
 47	// server did not advertise, so callers MUST gate the request on this.
 48	func (c *V2Capabilities) LSRefsSupports(feature string) bool {
 49		return c.commandSupports("ls-refs", feature)
 50	}
 51	
 52	// commandSupports reports whether feature appears in command's advertised
 53	// space-separated feature list.
 54	func (c *V2Capabilities) commandSupports(command, feature string) bool {
 55		if c == nil {
 56			return false
 57		}
 58		for _, f := range strings.Fields(c.Value(command)) {
 59			if f == feature {
 60				return true
 61			}
 62		}
 63		return false
 64	}
 65	
 66	// SortedKeys returns the capabilities as sorted "key" or "key=value" strings.
 67	func (c *V2Capabilities) SortedKeys() []string {
 68		if c == nil {
 69			return nil
 70		}
 71		keys := make([]string, 0, len(c.Caps))
 72		for k, v := range c.Caps {
 73			if v == "" {
 74				keys = append(keys, k)
 75			} else {
 76				keys = append(keys, k+"="+v)
 77			}
 78		}
 79		sort.Strings(keys)
 80		return keys
 81	}
 82	
 83	// RequestCapabilities builds the capability arguments for a v2 command request.
 84	func (c *V2Capabilities) RequestCapabilities() []string {
 85		var caps []string
 86		if agent := c.Value("agent"); agent != "" {
 87			caps = append(caps, "agent="+useragent.GoGit())
 88		}
 89		return caps
 90	}
 91	
 92	// DecodeV2Capabilities parses a protocol v2 capability advertisement from an
 93	// info/refs response body.
 94	func DecodeV2Capabilities(r io.Reader) (*V2Capabilities, error) {
 95		reader := NewPacketReader(r)
 96	
 97		// Skip service line and find "version 2\n"
 98		for {
 99			kind, payload, err := reader.ReadPacket()
100			if err != nil {
101				return nil, err
102			}
103			if kind == PacketFlush {
104				continue
105			}
106			if kind != PacketData {
107				return nil, fmt.Errorf("unexpected packet type %v before protocol advertisement", kind)
108			}
109			if strings.HasPrefix(string(payload), "# service=") {
110				continue
111			}
112			if string(payload) != "version 2\n" {
113				return nil, fmt.Errorf("unexpected protocol advertisement %q", payload)
114			}
115			break
116		}
117	
118		caps := &V2Capabilities{Caps: make(map[string]string)}
119		for {
120			kind, payload, err := reader.ReadPacket()
121			if err != nil {
122				return nil, err
123			}
124			if kind == PacketFlush {
125				return caps, nil
126			}
127			if kind != PacketData {
128				return nil, fmt.Errorf("unexpected packet type %v in capability advertisement", kind)
129			}
130			line := strings.TrimSuffix(string(payload), "\n")
131			name, value, _ := strings.Cut(line, "=")
132			caps.Caps[name] = value
133		}
134	}
135	
136	// PreferredSideband returns the best sideband capability supported by the
137	// server. Prefers sideband-64k over sideband (issue #4: sideband preference
138	// was backwards in original code).
139	func PreferredSideband(caps *capability.List) capability.Capability {
140		if caps.Supports(capability.Sideband64k) {
141			return capability.Sideband64k
142		}
143		if caps.Supports(capability.Sideband) {
144			return capability.Sideband
145		}
146		return ""
147	}

