func TestV2CapabilitiesFetchSupports(t *testing.T) {
	caps := &V2Capabilities{
		Caps: map[string]string{
			"fetch": "thin-pack filter",
			"agent": "git/test",
		},
	}

	tests := []struct {
		feature string
		want    bool
	}{
		{"filter", true},
		{"thin-pack", true},
		{"missing", false},
		{"thin", false},
		{"", false},
	}

	for _, tt := range tests {
		t.Run(tt.feature, func(t *testing.T) {
			got := caps.FetchSupports(tt.feature)
			if got != tt.want {
				t.Errorf("FetchSupports(%q) = %v, want %v", tt.feature, got, tt.want)
			}
		})
	}

	// nil receiver should always return false.
	var nilCaps *V2Capabilities
	if nilCaps.FetchSupports("filter") {
		t.Error("nil V2Capabilities.FetchSupports should return false")
	}
}

func TestV2CapabilitiesLSRefsSupports(t *testing.T) {
	caps := &V2Capabilities{
		Caps: map[string]string{
			"ls-refs": "unborn",
			"fetch":   "thin-pack",
		},
	}
	if !caps.LSRefsSupports("unborn") {
		t.Error(`LSRefsSupports("unborn") = false, want true`)
	}
	// Features are per-command: ls-refs must not answer for fetch's list, or
	// we would send an argument the server never advertised for this command.
	if caps.LSRefsSupports("thin-pack") {
		t.Error(`LSRefsSupports("thin-pack") = true; fetch features must not leak into ls-refs`)
	}
	if caps.FetchSupports("unborn") {
		t.Error(`FetchSupports("unborn") = true; ls-refs features must not leak into fetch`)
	}

	// A server advertising ls-refs with no feature list supports no features
	// — the common case for older servers, and the one that must keep the
	// unborn argument off the wire.
	bare := &V2Capabilities{Caps: map[string]string{"ls-refs": ""}}
	if bare.LSRefsSupports("unborn") {
		t.Error("bare ls-refs advertisement reported unborn support")
	}

	var nilCaps *V2Capabilities
	if nilCaps.LSRefsSupports("unborn") {
		t.Error("nil V2Capabilities.LSRefsSupports should return false")
	}
}

func TestV2CapabilitiesSortedKeys(t *testing.T) {
	caps := &V2Capabilities{
		Caps: map[string]string{
			"fetch":   "shallow",
			"ls-refs": "",
			"agent":   "git/test",
		},
	}

	got := caps.SortedKeys()
	want := []string{
		"agent=git/test",
		"fetch=shallow",
		"ls-refs",
	}
	if len(got) != len(want) {
		t.Fatalf("SortedKeys() returned %d items, want %d", len(got), len(want))
	}
	for i := range got {
		if got[i] != want[i] {
			t.Errorf("SortedKeys()[%d] = %q, want %q", i, got[i], want[i])
		}
	}

	// nil receiver should return nil.
	var nilCaps *V2Capabilities
	if keys := nilCaps.SortedKeys(); keys != nil {
		t.Errorf("nil V2Capabilities.SortedKeys() = %v, want nil", keys)
	}
}

func TestV2CapabilitiesSupportsAndValue(t *testing.T) {
	caps := &V2Capabilities{
		Caps: map[string]string{
			"fetch":   "shallow",
			"ls-refs": "",
		},
	}

	if !caps.Supports("fetch") {
		t.Error("expected Supports(fetch) = true")
	}
	if !caps.Supports("ls-refs") {
		t.Error("expected Supports(ls-refs) = true")
	}
	if caps.Supports("push") {
		t.Error("expected Supports(push) = false")
	}
	if got := caps.Value("fetch"); got != "shallow" {
		t.Errorf("Value(fetch) = %q, want %q", got, "shallow")
	}
	if got := caps.Value("ls-refs"); got != "" {
		t.Errorf("Value(ls-refs) = %q, want empty", got)
	}
	if got := caps.Value("push"); got != "" {
		t.Errorf("Value(push) = %q, want empty", got)
	}

	// nil receiver tests.
	var nilCaps *V2Capabilities
	if nilCaps.Supports("fetch") {
		t.Error("nil V2Capabilities.Supports should return false")
	}
	if got := nilCaps.Value("fetch"); got != "" {
		t.Errorf("nil V2Capabilities.Value should return empty, got %q", got)
	}
}

