new = '''// DecodeV2Capabilities parses a protocol v2 capability advertisement from an
// info/refs response body.
//
// The pkt-line walk is go-git's (packp.CapabilityAdv), so git-sync does not
// carry its own copy of the v2 advertisement grammar. Only the tolerance
// prelude is ours: CapabilityAdv.Decode requires the "version 2" line to be
// the very first packet, whereas callers here hand over a whole /info/refs
// body, which over smart HTTP is preceded by the "# service=" banner and its
// flush. go-git's own HTTP transport strips those in handshakeSmart before
// calling Decode; the SSH and remote-helper transports deliver the
// advertisement bannerless, and a leading flush has always been tolerated.
func DecodeV2Capabilities(r io.Reader) (*V2Capabilities, error) {
	// Sized for the largest legal pkt-line so PeekLine can always see a whole
	// packet: it peeks length-many bytes, which bufio refuses past its buffer.
	br := bufio.NewReaderSize(r, pktline.MaxSize)

	for {
		length, payload, err := pktline.PeekLine(br)
		if err != nil {
			return nil, fmt.Errorf("read v2 capability advertisement: %w", err)
		}
		isBanner := bytes.HasPrefix(payload, []byte("# service="))
		isSpecial := length == pktline.Flush || length == pktline.Delim || length == pktline.ResponseEnd
		if !isBanner && !isSpecial {
			break
		}
		if _, _, err := pktline.ReadLine(br); err != nil {
			return nil, fmt.Errorf("read v2 capability advertisement: %w", err)
		}
	}

	adv := &packp.CapabilityAdv{}
	if err := adv.Decode(br); err != nil {
		return nil, fmt.Errorf("decode v2 capability advertisement: %w", err)
	}

	// Flatten go-git's per-capability value slices back into the
	// space-separated form the advertisement carries them in. DecodeListV2
	// splits "fetch=shallow filter" into two values; every caller here wants
	// either the whole string (Value, SortedKeys) or a membership test
	// (commandSupports), and joining keeps both honest for capabilities whose
	// value is a single opaque token (agent, object-format).
	names := adv.Capabilities.All()
	caps := &V2Capabilities{Caps: make(map[string]string, len(names))}
	for _, name := range names {
		caps.Caps[name] = strings.Join(adv.Capabilities.Get(name), " ")
	}
	return caps, nil
}

