// v2FetchEnvelopeError maps a FetchOutput decode outcome that yielded no
// packfile onto the errors git-sync's callers and tests already expect.
//
// The "ready" distinction is read off the decoded acknowledgments rather than
// off the error text: a server that said "ready" promised a packfile, so its
// absence is a protocol violation worth naming, whereas a plain
// acknowledgments-then-flush is an ordinary negotiation round that arrived
// where a final response was required.
func v2FetchEnvelopeError(out *packp.FetchOutput, err error) error {
	var errLine *pktline.ErrorLine
	if errors.As(err, &errLine) {
		return errors.New("remote: " + errLine.Text)
	}

	ready := out != nil && out.Acknowledgments != nil && out.Acknowledgments.Ready
	if ready {
		return errors.New("expected packfile to be sent after 'ready'")
	}
	if err != nil {
		return fmt.Errorf("decode protocol v2 fetch response: %w", err)
	}
	if out != nil && out.Acknowledgments != nil {
		return errors.New("protocol v2 fetch response ended without packfile after acknowledgments")
	}
	// A clean flush or EOF with no sections at all: the server owed a packfile
	// and closed instead.
	return io.ErrUnexpectedEOF
