func storeV2FetchPack(store storer.Storer, r io.Reader, verbose bool, progressOut io.Writer) error {
	return consumeV2FetchPack(r, verbose, progressOut, func(packReader io.Reader) error {
		if err := packfile.UpdateObjectStorage(store, packReader); err != nil {
			return fmt.Errorf("update object storage: %w", err)
		}
		return nil
	})
}

// consumeV2FetchPack walks a protocol v2 fetch response envelope
// (acknowledgments / shallow-info / packfile sections) and hands the
// demuxed packfile stream to consumer. A response that ends without ever
// delivering a packfile is reported as an error rather than as silent success:
// by the time we reach here wants is non-empty (callers short-circuit the
// up-to-date case earlier), so the server owes us a packfile section.
func consumeV2FetchPack(
	r io.Reader,
	verbose bool,
	progressOut io.Writer,
	consumer func(io.Reader) error,
) error {
	br, err := openV2Packfile(r, verbose, progressOut)
	if err != nil {
		return err
	}
	return consumer(br)
}

func openV2PackStream(body io.ReadCloser, verbose bool, progressOut io.Writer) (io.ReadCloser, error) {
	demux, err := openV2Packfile(body, verbose, progressOut)
	if err != nil {
		return nil, err
	}
	return &wrappedRC{Reader: demux, Closer: body}, nil
}

// openV2Packfile advances r past the v2 fetch response metadata sections and
// returns a reader over the sideband-demuxed packfile.
//
// The envelope grammar is go-git's (packp.FetchOutput), so git-sync no longer
// carries its own copy of it. That also buys section-order and
// no-repeat validation, plus tolerance of the wanted-refs and packfile-uris
// sections, none of which the hand-rolled walk this replaced had.
func openV2Packfile(r io.Reader, verbose bool, progressOut io.Writer) (io.Reader, error) {
	br, ok := r.(*bufio.Reader)
	if !ok {
		br = bufio.NewReaderSize(r, 65536)
	}

	out := &packp.FetchOutput{}
	decErr := out.Decode(br)
	if decErr != nil || !out.Packfile {
		return nil, v2FetchEnvelopeError(out, decErr)
	}

	demux := sideband.NewDemuxer(sideband.Sideband64k, br)
	demux.Progress = progressSink(verbose, "source: ", progressOut)
	return demux, nil
}

